'use client'

import { useEffect, useMemo, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, BarChart3, BookOpen, Check, ChevronDown, ClipboardList, GraduationCap, LayoutDashboard, LoaderCircle, LockKeyhole, LogOut, Menu, Plus, Search, Settings, ShieldCheck, Sparkles, UserRound, Users, X } from 'lucide-react'

type BaptismalClass = { id: string; class_name: string; class_teacher: string; assistant_teacher: string }
type Registration = { id: string; full_name: string; matric_number: string; gender: string; level: string; department: string; baptismal_class_id: string; reason_for_baptism: string; class_feedback: string | null; registration_date: string }
type ResultRow = { id?: string; student_name: string; matric_number: string; baptismal_class_id: string; examination_score: number | string; result_status?: string; remarks: string }
const supabase = createClient()
const navItems = [
  { label: 'Overview', icon: LayoutDashboard }, { label: 'Student registrations', icon: Users },
  { label: 'Manage classes', icon: BookOpen }, { label: 'Examination results', icon: ClipboardList },
  { label: 'Upload results', icon: ArrowDownToLine }, { label: 'Teachers & assistants', icon: GraduationCap },
  { label: 'Reports & analytics', icon: BarChart3 }, { label: 'Settings', icon: Settings },
]
const fieldClass = 'w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-emerald-600 focus:ring-4 focus:ring-emerald-600/10'
const classesLabel = 'mb-2 block text-xs font-semibold uppercase tracking-[.1em] text-slate-500'
const formatDate = (value: string) => new Intl.DateTimeFormat('en-NG', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value))

export default function RucManagementApp() {
  const [classes, setClasses] = useState<BaptismalClass[]>([])
  const [route, setRoute] = useState<'register' | 'login' | 'dashboard'>('register')
  const [activePage, setActivePage] = useState('Overview')
  const [busy, setBusy] = useState(false)
  const [notice, setNotice] = useState('')
  const [registrationSubmitted, setRegistrationSubmitted] = useState(false)
  const [selectedClass, setSelectedClass] = useState('')
  const [mobileMenu, setMobileMenu] = useState(false)
  const [user, setUser] = useState<{ id: string; email?: string } | null>(null)
  const [staffRole, setStaffRole] = useState<string | null>(null)
  const [registrations, setRegistrations] = useState<Registration[]>([])
  const [results, setResults] = useState<(ResultRow & { result_status: string })[]>([])
  const [passMark, setPassMark] = useState(35)
  const [search, setSearch] = useState('')
  const [filterClass, setFilterClass] = useState('all')
  const [form, setForm] = useState({ full_name: '', matric_number: '', gender: '', level: '', department: '', completed: '', class_id: '', reason: '', feedback: '' })
  const selected = classes.find((item) => item.id === form.class_id)

  useEffect(() => {
    const loadClasses = async () => {
      const { data } = await supabase.from('baptismal_classes').select('id,class_name,class_teacher,assistant_teacher').order('class_name')
      if (data) setClasses(data as BaptismalClass[])
    }
    void loadClasses()
    void supabase.auth.getUser().then(({ data }) => { if (data.user) setUser({ id: data.user.id, email: data.user.email }) })
  }, [])

  useEffect(() => {
    if (route !== 'dashboard' || !user) return
    const loadDashboard = async () => {
      setBusy(true)
      const [profile, studentRows, resultRows, settings] = await Promise.all([
        supabase.from('staff_profiles').select('role').eq('user_id', user.id).maybeSingle(),
        supabase.from('student_registrations').select('id,full_name,matric_number,gender,level,department,baptismal_class_id,reason_for_baptism,class_feedback,registration_date').order('registration_date', { ascending: false }),
        supabase.from('examination_results').select('id,student_name,matric_number,baptismal_class_id,examination_score,result_status,remarks').order('created_at', { ascending: false }),
        supabase.from('system_settings').select('examination_pass_mark').eq('id', true).maybeSingle(),
      ])
      setStaffRole(profile.data?.role ?? null)
      setRegistrations((studentRows.data ?? []) as Registration[])
      setResults((resultRows.data ?? []) as (ResultRow & { result_status: string })[])
      if (settings.data) setPassMark(Number(settings.data.examination_pass_mark))
      if (studentRows.error || resultRows.error) setNotice('Could not load staff data. Confirm your staff account is set up and sign in again.')
      setBusy(false)
    }
    void loadDashboard()
  }, [route, user])

  const submitRegistration = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (form.completed !== 'yes') { setNotice('You must successfully complete and pass your baptismal class before proceeding with baptismal registration.'); return }
    setBusy(true); setNotice(''); setRegistrationSubmitted(false)
    const matric = form.matric_number.trim().toUpperCase()
    if (!/^[A-Z0-9][A-Z0-9/-]{3,19}$/.test(matric)) { setNotice('Enter a valid matriculation number (4–20 letters or numbers).'); setBusy(false); return }
    const { error } = await supabase.from('student_registrations').insert({ full_name: form.full_name.trim(), matric_number: matric, gender: form.gender, level: form.level, department: form.department.trim(), completed_and_passed: true, baptismal_class_id: form.class_id, reason_for_baptism: form.reason.trim(), class_feedback: form.feedback.trim() || null })
    if (error?.code === '23505') setNotice('A registration with this matriculation number already exists.')
    else if (error) setNotice('Registration could not be saved. Please check your details and try again.')
    else { setNotice('Registration received. Your details have been securely submitted.'); setRegistrationSubmitted(true); setForm({ full_name: '', matric_number: '', gender: '', level: '', department: '', completed: '', class_id: '', reason: '', feedback: '' }) }
    setBusy(false)
  }

  const signIn = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setBusy(true); setNotice('')
    const values = new FormData(event.currentTarget)
    const response = await fetch('/api/admin/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ password: String(values.get('password') ?? '') }) })
    const result = await response.json().catch(() => ({})) as { error?: string }
    if (!response.ok) setNotice(result.error ?? 'Administrator sign in failed. Please try again.')
    else {
      const { data } = await supabase.auth.getUser()
      if (data.user) { setUser({ id: data.user.id, email: data.user.email }); setRoute('dashboard') }
      else setNotice('Sign in completed, but your secure session could not be read. Please try again.')
    }
    setBusy(false)
  }

  const signOut = async () => { await supabase.auth.signOut(); setUser(null); setStaffRole(null); setRoute('register'); setNotice('') }
  const filteredRegs = useMemo(() => registrations.filter((row) => {
    const matchSearch = `${row.full_name} ${row.matric_number} ${row.department}`.toLowerCase().includes(search.toLowerCase())
    return matchSearch && (filterClass === 'all' || row.baptismal_class_id === filterClass)
  }), [registrations, search, filterClass])
  const stats = useMemo(() => ({ passed: results.filter((row) => Number(row.examination_score) >= passMark).length, failed: results.filter((row) => Number(row.examination_score) < passMark).length, pending: Math.max(registrations.length - results.length, 0) }), [results, registrations, passMark])

  if (route === 'login') return <Login onSubmit={signIn} busy={busy} notice={notice} onBack={() => { setRoute('register'); setNotice('') }} />
  if (route === 'dashboard') return <Dashboard {...{ activePage, setActivePage, classes, registrations, filteredRegs, results, stats, busy, notice, setNotice, setRoute, signOut, search, setSearch, filterClass, setFilterClass, user, staffRole, passMark, setPassMark, setClasses, setRegistrations, setResults }} mobileMenu={mobileMenu} setMobileMenu={setMobileMenu} />

  return <main className="min-h-screen bg-[#f5f7f8] text-slate-900">
    <header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-5 sm:px-8">
      <a className="flex items-center gap-3" href="#home" aria-label="Redeemer's University home"><span className="flex size-11 items-center justify-center rounded-2xl bg-[#102a43] text-white"><BookOpen size={21} /></span><span><span className="block text-sm font-bold tracking-tight text-slate-900">REDEEMER&apos;S UNIVERSITY</span><span className="mt-0.5 block text-[10px] font-semibold tracking-[.2em] text-slate-500">TRAINING DEPARTMENT</span></span></a>
      <button type="button" onClick={() => { setNotice(''); setRoute('login') }} className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:border-emerald-600 hover:text-emerald-800"><LockKeyhole size={15} /> Administrator login</button>
    </header>
    <section id="home" className="mx-auto grid max-w-7xl items-center gap-10 px-5 pb-14 pt-6 sm:px-8 md:grid-cols-[1.05fr_.95fr] md:gap-16 md:pb-24 md:pt-14">
      <div className="relative order-2 md:order-1"><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-emerald-100 bg-emerald-50 px-3.5 py-2 text-xs font-semibold text-emerald-900"><Sparkles size={14} /> Your next step in faith</div><h1 className="max-w-2xl text-4xl font-semibold leading-[1.1] tracking-[-.045em] text-[#102a43] sm:text-5xl lg:text-[3.75rem]">Take the next step<br className="hidden sm:block" /> in your <span className="text-emerald-700">faith journey.</span></h1><p className="mt-6 max-w-lg text-base leading-7 text-slate-600">A meaningful commitment deserves a thoughtful beginning. Complete your baptismal registration with the RUC Training Department.</p>
        <div className="mt-9 flex flex-wrap items-center gap-x-6 gap-y-3 text-xs font-medium text-slate-500"><span className="flex items-center gap-2"><ShieldCheck size={16} className="text-emerald-700" /> Your details are kept secure</span><span className="flex items-center gap-2"><Check size={16} className="text-emerald-700" /> About 3 minutes to complete</span></div>
        <div className="mt-12 hidden max-w-sm items-center gap-4 rounded-2xl border border-slate-200/80 bg-white/80 p-4 shadow-sm md:flex"><span className="flex size-10 items-center justify-center rounded-xl bg-emerald-50 text-emerald-800"><GraduationCap size={19} /></span><div><p className="text-sm font-semibold text-slate-800">A community walking together</p><p className="mt-1 text-xs text-slate-500">Supported by your class teacher every step.</p></div><ArrowRight size={17} className="ml-auto text-slate-400" /></div>
      </div>
      <section className="order-1 rounded-[1.6rem] border border-slate-200/80 bg-white p-5 shadow-[0_20px_70px_-40px_rgba(16,42,67,.25)] sm:p-8 md:order-2 md:p-9" aria-labelledby="registration-heading">
        <div className="mb-7 flex items-start justify-between gap-4"><div><p className="text-[11px] font-bold tracking-[.17em] text-emerald-700">STUDENT PORTAL</p><h2 id="registration-heading" className="mt-2 text-2xl font-semibold tracking-tight text-[#102a43]">Baptismal registration</h2><p className="mt-2 text-sm leading-6 text-slate-500">Congratulations on completing your baptismal class. Kindly provide the following information to proceed with your baptismal registration.</p></div><span className="hidden size-11 shrink-0 items-center justify-center rounded-xl bg-[#edf3f1] text-emerald-800 sm:flex"><ClipboardList size={20} /></span></div>
        {notice && <div role="status" className={`mb-5 rounded-xl border px-4 py-3 text-sm ${notice.startsWith('Registration received') ? 'border-emerald-200 bg-emerald-50 text-emerald-900' : 'border-amber-200 bg-amber-50 text-amber-900'}`}>{notice}</div>}
        {registrationSubmitted ? <div className="rounded-2xl border border-emerald-200 bg-emerald-50 p-5 sm:p-6"><span className="flex size-11 items-center justify-center rounded-full bg-white text-emerald-700"><Check size={21} /></span><h3 className="mt-4 text-lg font-semibold text-[#102a43]">Registration complete</h3><p className="mt-2 text-sm leading-6 text-slate-600">Your details have been securely submitted. Joining the baptismal WhatsApp group is compulsory for everyone proceeding to baptism.</p><a className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-[#102a43] px-5 py-3.5 text-sm font-semibold text-white transition hover:bg-[#163c5b]" href="https://chat.whatsapp.com/CrVYgVPQLtz9FMroe2eMBm?s=sw&amp;p=a&amp;iam=2" target="_blank" rel="noopener noreferrer">Join the compulsory WhatsApp group <ArrowRight size={16} /></a></div> : <form onSubmit={submitRegistration} className="grid grid-cols-1 gap-x-4 gap-y-4 sm:grid-cols-2">
          <label className="sm:col-span-2"><span className={classesLabel}>Full name <Required /></span><input className={fieldClass} autoComplete="name" required maxLength={120} placeholder="Enter your full name" value={form.full_name} onChange={(e) => setForm({ ...form, full_name: e.target.value })} /></label>
          <label><span className={classesLabel}>Matriculation number <Required /></span><input className={fieldClass} required maxLength={20} autoCapitalize="characters" placeholder="e.g. RUN/2023/1234" value={form.matric_number} onChange={(e) => setForm({ ...form, matric_number: e.target.value.toUpperCase() })} /></label>
          <SelectField label="Gender" value={form.gender} onChange={(v) => setForm({ ...form, gender: v })} options={['Male', 'Female']} placeholder="Choose gender" />
          <SelectField label="Level" value={form.level} onChange={(v) => setForm({ ...form, level: v })} options={['100', '200', '300', '400', '500']} placeholder="Choose level" suffix=" Level" />
          <label><span className={classesLabel}>Department <Required /></span><input className={fieldClass} required maxLength={120} placeholder="Your department" value={form.department} onChange={(e) => setForm({ ...form, department: e.target.value })} /></label>
          <SelectField label="Completed and passed your baptismal class?" value={form.completed} onChange={(v) => { setForm({ ...form, completed: v }); if (v === 'no') setNotice('You must successfully complete and pass your baptismal class before proceeding with baptismal registration.'); else setNotice('') }} options={['yes', 'no']} labels={['Yes, I have', 'No, not yet']} placeholder="Select an answer" wide />
          {form.completed === 'no' && <div className="sm:col-span-2 -mt-1 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm leading-5 text-amber-900">You must successfully complete and pass your baptismal class before proceeding with baptismal registration.</div>}
          <label className="sm:col-span-2"><span className={classesLabel}>Baptismal class <Required /></span><span className="relative block"><select className={`${fieldClass} appearance-none pr-10`} required value={form.class_id} onChange={(e) => setForm({ ...form, class_id: e.target.value })}><option value="">Select your class</option>{classes.map((item) => <option key={item.id} value={item.id}>{item.class_name}</option>)}</select><ChevronDown size={16} className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" /></span></label>
          {selected && <div className="sm:col-span-2 rounded-2xl border border-emerald-100 bg-[#f5faf7] p-4"><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.12em] text-emerald-800"><Users size={15} /> Your class team</div><div className="mt-3 grid grid-cols-1 gap-3 sm:grid-cols-2"><TeacherTile title="Class teacher" name={selected.class_teacher} /><TeacherTile title="Assistant teacher" name={selected.assistant_teacher} /></div></div>}
          <label className="sm:col-span-2"><span className={classesLabel}>Why do you want to get baptized? <Required /></span><textarea className={`${fieldClass} min-h-[100px] resize-y`} required maxLength={1200} placeholder="Share a little about what baptism means to you…" value={form.reason} onChange={(e) => setForm({ ...form, reason: e.target.value })} /></label>
          <label className="sm:col-span-2"><span className={classesLabel}>Feedback on your class experience <span className="normal-case tracking-normal text-slate-400">(Optional)</span></span><textarea className={`${fieldClass} min-h-[78px] resize-y`} maxLength={1200} placeholder="Anything you would like us to know?" value={form.feedback} onChange={(e) => setForm({ ...form, feedback: e.target.value })} /></label>
          <button disabled={busy || !classes.length || form.completed === 'no'} type="submit" className="mt-2 flex w-full items-center justify-center gap-2 rounded-xl bg-[#102a43] px-5 py-3.5 text-sm font-semibold text-white shadow-lg shadow-[#102a43]/10 transition hover:bg-[#163c5b] disabled:cursor-not-allowed disabled:opacity-60 sm:col-span-2">{busy ? <LoaderCircle size={17} className="animate-spin" /> : <Check size={16} />} Submit baptismal registration</button>
          <p className="flex items-center justify-center gap-1.5 text-center text-[11px] text-slate-400 sm:col-span-2"><LockKeyhole size={12} /> Your personal information is submitted securely.</p>
        </form>}
      </section>
    </section>
    <footer className="border-t border-slate-200/80 bg-white"><div className="mx-auto flex max-w-7xl flex-col gap-2 px-5 py-6 text-xs text-slate-500 sm:flex-row sm:items-center sm:justify-between sm:px-8"><span>© {new Date().getFullYear()} Redeemer&apos;s University Christian Training Department</span><button type="button" className="w-fit font-semibold text-slate-600 hover:text-emerald-800" onClick={() => setRoute('login')}>Administrator sign in</button></div></footer>
  </main>
}

function Required() { return <span aria-hidden="true" className="text-rose-600">*</span> }
function SelectField({ label, value, onChange, options, placeholder, suffix = '', labels, wide = false }: { label: string; value: string; onChange: (value: string) => void; options: string[]; placeholder: string; suffix?: string; labels?: string[]; wide?: boolean }) {
  return <label className={wide ? 'sm:col-span-2' : ''}><span className={classesLabel}>{label} <Required /></span><span className="relative block"><select className={`${fieldClass} appearance-none pr-10`} required value={value} onChange={(e) => onChange(e.target.value)}><option value="">{placeholder}</option>{options.map((option, index) => <option key={option} value={option}>{labels?.[index] ?? `${option}${suffix}`}</option>)}</select><ChevronDown size={16} className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" /></span></label>
}
function TeacherTile({ title, name }: { title: string; name: string }) { return <div className="flex items-center gap-3 rounded-xl border border-emerald-100/80 bg-white px-3 py-2.5"><span className="flex size-8 shrink-0 items-center justify-center rounded-full bg-emerald-50 text-emerald-800"><UserRound size={15} /></span><span><span className="block text-[10px] font-semibold uppercase tracking-wider text-slate-400">{title}</span><span className="mt-0.5 block text-sm font-semibold text-slate-800">{name}</span></span></div> }

function Login({ onSubmit, busy, notice, onBack }: { onSubmit: (event: React.FormEvent<HTMLFormElement>) => void; busy: boolean; notice: string; onBack: () => void }) {
  return <main className="flex min-h-screen items-center justify-center bg-[#f5f7f8] px-5 py-12"><div className="w-full max-w-md"><button onClick={onBack} className="mb-8 flex items-center gap-2 text-sm font-semibold text-slate-500 transition hover:text-slate-900"><ArrowLeft size={16} /> Return to registration</button><div className="rounded-[1.6rem] border border-slate-200 bg-white p-7 shadow-xl shadow-slate-900/5 sm:p-9"><div className="flex size-12 items-center justify-center rounded-2xl bg-[#102a43] text-white"><LockKeyhole size={20} /></div><p className="mt-6 text-xs font-bold tracking-[.16em] text-emerald-700">ADMINISTRATOR PORTAL</p><h1 className="mt-2 text-3xl font-semibold tracking-tight text-[#102a43]">Welcome back</h1><p className="mt-2 text-sm leading-6 text-slate-500">Enter the administrator password to manage classes, registrations and examination results.</p>{notice && <div role="alert" className="mt-5 rounded-xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-800">{notice}</div>}<form className="mt-7 flex flex-col gap-5" onSubmit={onSubmit}><label><span className={classesLabel}>Administrator password</span><input className={fieldClass} name="password" type="password" required autoComplete="current-password" placeholder="Enter admin password" /></label><button disabled={busy} className="mt-1 flex items-center justify-center gap-2 rounded-xl bg-[#102a43] px-4 py-3.5 text-sm font-semibold text-white hover:bg-[#163c5b] disabled:opacity-60">{busy ? <LoaderCircle size={16} className="animate-spin" /> : <LockKeyhole size={15} />} Sign in as administrator</button></form><p className="mt-6 text-center text-xs leading-5 text-slate-400">Administrator access is protected by a secure sign-in session.</p></div></div></main>
}

type DashboardProps = { activePage: string; setActivePage: (v: string) => void; classes: BaptismalClass[]; registrations: Registration[]; filteredRegs: Registration[]; results: (ResultRow & { result_status: string })[]; stats: { passed: number; failed: number; pending: number }; busy: boolean; notice: string; setNotice: (v: string) => void; setRoute: (v: 'register' | 'login' | 'dashboard') => void; signOut: () => void; search: string; setSearch: (v: string) => void; filterClass: string; setFilterClass: (v: string) => void; user: { id: string; email?: string } | null; staffRole: string | null; passMark: number; setPassMark: (v: number) => void; setClasses: (v: BaptismalClass[]) => void; setRegistrations: (v: Registration[]) => void; setResults: (v: (ResultRow & { result_status: string })[]) => void; mobileMenu: boolean; setMobileMenu: (v: boolean) => void }

function Dashboard(props: DashboardProps) {
 const { activePage, setActivePage, classes, registrations, filteredRegs, results, stats, busy, notice, setNotice, setRoute, signOut, search, setSearch, filterClass, setFilterClass, user, staffRole, passMark, setPassMark, setClasses, setRegistrations, setResults, mobileMenu, setMobileMenu } = props
 const [classChoice, setClassChoice] = useState(''); const [newClass, setNewClass] = useState({ class_name: '', class_teacher: '', assistant_teacher: '' }); const [rows, setRows] = useState<ResultRow[]>([{ student_name: '', matric_number: '', baptismal_class_id: '', examination_score: '', remarks: '' }]); const [saving, setSaving] = useState(false); const [detail, setDetail] = useState<Registration | null>(null); const [passwordNotice, setPasswordNotice] = useState('')
 const refresh = async () => { const [s, r] = await Promise.all([supabase.from('student_registrations').select('id,full_name,matric_number,gender,level,department,baptismal_class_id,reason_for_baptism,class_feedback,registration_date').order('registration_date', { ascending: false }), supabase.from('examination_results').select('id,student_name,matric_number,baptismal_class_id,examination_score,result_status,remarks').order('created_at', { ascending: false })]); setRegistrations((s.data ?? []) as Registration[]); setResults((r.data ?? []) as (ResultRow & { result_status: string })[]) }
 const exportCsv = (header: string[], data: string[][], filename: string) => { const text = [header, ...data].map((line) => line.map((v) => `"${String(v ?? '').replaceAll('"', '""')}"`).join(',')).join('\n'); const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([text], { type: 'text/csv;charset=utf-8' })); a.download = filename; a.click(); URL.revokeObjectURL(a.href) }
 const addClass = async (e: React.FormEvent) => { e.preventDefault(); const { data, error } = await supabase.from('baptismal_classes').insert(newClass).select('id,class_name,class_teacher,assistant_teacher').single(); if (error) setNotice('Unable to add class. Admin authorization is required.'); else if (data) { setClasses([...classes, data as BaptismalClass]); setNewClass({ class_name: '', class_teacher: '', assistant_teacher: '' }); setNotice('Class added successfully.') } }
 const removeClass = async (id: string) => { if (!window.confirm('Remove this baptismal class? Classes with linked students cannot be removed.')) return; const { error } = await supabase.from('baptismal_classes').delete().eq('id', id); if (error) setNotice('Class could not be removed. It may still have student or examination records.'); else { setClasses(classes.filter((c) => c.id !== id)); setNotice('Class removed.') } }
 const saveResults = async () => { const valid = rows.filter((r) => r.student_name.trim() && r.matric_number.trim() && r.examination_score !== ''); if (!classChoice) { setNotice('Select a class before saving results.'); return } if (!valid.length) { setNotice('Add at least one complete student result.'); return } const normalized = valid.map((r) => ({ student_name: r.student_name.trim(), matric_number: r.matric_number.trim().toUpperCase(), baptismal_class_id: classChoice, examination_score: Number(r.examination_score), result_status: Number(r.examination_score) >= passMark ? 'PASS' : 'FAIL', remarks: r.remarks.trim(), uploaded_by: user?.id }))
 if (normalized.some((r) => !Number.isFinite(r.examination_score) || r.examination_score < 0 || r.examination_score > 70)) { setNotice('Scores must be numbers between 0 and 70.'); return }
 if (new Set(normalized.map((r) => r.matric_number)).size !== normalized.length) { setNotice('Remove duplicate matriculation numbers from this upload.'); return }
 setSaving(true); const { error } = await supabase.from('examination_results').upsert(normalized, { onConflict: 'baptismal_class_id,matric_number' }); if (error) setNotice('Results could not be saved. Confirm your assigned class and staff permissions.'); else { setNotice(`${normalized.length} result${normalized.length === 1 ? '' : 's'} saved.`); setRows([{ student_name: '', matric_number: '', baptismal_class_id: '', examination_score: '', remarks: '' }]); await refresh() } setSaving(false) }
 const uploadCsv = async (file?: File) => { if (!file) return; const text = await file.text(); const parsed = text.split(/\r?\n/).filter(Boolean).slice(1).map((line) => { const cols = line.split(',').map((v) => v.trim().replace(/^"|"$/g, '')); return { student_name: cols[0] ?? '', matric_number: cols[1] ?? '', examination_score: cols[2] ?? '', remarks: cols[3] ?? '', baptismal_class_id: classChoice } }); if (!classChoice) { setNotice('Select a class before importing a file.'); return } setRows(parsed.length ? parsed : rows); setNotice(`Previewing ${parsed.length} rows. Review the table and select Save results to continue.`) }
 const classCounts = classes.map((c) => { const enrolled = registrations.filter((r) => r.baptismal_class_id === c.id).length; const classResults = results.filter((r) => r.baptismal_class_id === c.id); const passed = classResults.filter((r) => Number(r.examination_score) >= passMark).length; const failed = classResults.filter((r) => Number(r.examination_score) < passMark).length; return { ...c, enrolled, passed, failed } })
 const titleByPage: Record<string, string> = { Overview: 'Welcome to your dashboard', 'Student registrations': 'Student registrations', 'Manage classes': 'Baptismal classes', 'Examination results': 'Examination results', 'Upload results': 'Upload student results', 'Teachers & assistants': 'Teachers & assistants', 'Reports & analytics': 'Reports & analytics', Settings: 'Department settings' }
 return <div className="min-h-screen bg-[#f5f7f8] text-slate-900">
  {mobileMenu && <button aria-label="Close menu" onClick={() => setMobileMenu(false)} className="fixed inset-0 bg-slate-950/40 md:hidden" />}
  <aside className={`fixed inset-y-0 left-0 z-20 flex h-dvh w-[min(84vw,300px)] flex-col overflow-y-auto border-r border-slate-200 bg-white px-4 py-5 transition-transform md:w-[260px] md:translate-x-0 ${mobileMenu ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex items-center gap-3 px-2"><span className="flex size-10 items-center justify-center rounded-xl bg-[#102a43] text-white"><BookOpen size={19} /></span><span><b className="block text-xs tracking-wide text-[#102a43]">RUC TRAINING</b><span className="text-[10px] text-slate-400">Department workspace</span></span><button className="ml-auto md:hidden" onClick={() => setMobileMenu(false)} aria-label="Close navigation"><X size={18} /></button></div><div className="mt-9 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-slate-400">Workspace</div><nav className="mt-3 flex flex-col gap-1">{navItems.map(({ label, icon: Icon }) => <button key={label} onClick={() => { setActivePage(label); setMobileMenu(false) }} className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-left text-[13px] font-medium transition ${activePage === label ? 'bg-[#edf3f1] text-emerald-900' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}><Icon size={17} />{label}{activePage === label && <span className="ml-auto size-1.5 rounded-full bg-emerald-600" />}</button>)}</nav><div className="mt-auto rounded-2xl bg-[#f5f7f8] p-4"><div className="flex items-center gap-2 text-xs font-semibold text-slate-700"><ShieldCheck size={15} className="text-emerald-700" /> Protected workspace</div><p className="mt-2 text-[11px] leading-5 text-slate-500">Only authorized department staff can access student records.</p></div><button onClick={() => { void signOut(); setRoute('register') }} className="mt-3 flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-medium text-slate-500 hover:bg-rose-50 hover:text-rose-700"><LogOut size={17} /> Sign out</button></aside>
  <div className="min-h-screen md:pl-[260px]"><header className="sticky top-0 z-10 flex h-[68px] items-center justify-between border-b border-slate-200 bg-white/95 px-5 backdrop-blur sm:px-8"><div className="flex items-center gap-3"><button aria-label="Open navigation" onClick={() => setMobileMenu(true)} className="md:hidden"><Menu size={20} /></button><span className="text-xs font-medium text-slate-400">RUC Training <span className="mx-2">/</span><span className="text-slate-700">{activePage}</span></span></div><div className="flex items-center gap-3"><span className="hidden text-right sm:block"><span className="block text-xs font-semibold text-slate-700">{user?.email ?? 'Staff member'}</span><span className="text-[10px] capitalize text-slate-400">{staffRole ?? 'staff account'}</span></span><span className="flex size-9 items-center justify-center rounded-full bg-emerald-50 text-xs font-bold text-emerald-800">{user?.email?.slice(0, 1).toUpperCase() ?? 'R'}</span></div></header>
  <main className="mx-auto max-w-[1400px] px-5 py-7 sm:px-8 sm:py-9"><div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[.15em] text-emerald-700">RUC TRAINING DEPARTMENT</p><h1 className="mt-2 text-2xl font-semibold tracking-tight text-[#102a43] sm:text-[1.8rem]">{titleByPage[activePage]}</h1><p className="mt-1.5 text-sm text-slate-500">{activePage === 'Overview' ? 'Here is what’s happening across your baptismal classes.' : 'Manage your department information and student records.'}</p></div>{activePage === 'Student registrations' && <button onClick={() => exportCsv(['Full name','Matric number','Gender','Level','Department','Class','Teacher','Registration date'], filteredRegs.map((r) => { const c=classes.find((x)=>x.id===r.baptismal_class_id); return [r.full_name,r.matric_number,r.gender,r.level,r.department,c?.class_name ?? '',c?.class_teacher ?? '',r.registration_date] }), 'ruc-registrations.csv')} className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 hover:border-emerald-500"><ArrowDownToLine size={16} /> Export CSV</button>}</div>
 {notice && <div role="status" className="mb-5 flex items-center justify-between gap-4 rounded-xl border border-emerald-100 bg-emerald-50 px-4 py-3 text-sm text-emerald-900">{notice}<button onClick={() => setNotice('')} aria-label="Dismiss notification"><X size={16} /></button></div>}
 {busy && <div className="mb-4 flex items-center gap-2 text-xs text-slate-400"><LoaderCircle size={14} className="animate-spin" /> Loading records…</div>}
 {staffRole === null && !busy ? <section className="rounded-2xl border border-amber-200 bg-amber-50 p-6"><h2 className="font-semibold text-amber-950">Staff access is not configured</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-amber-900">Your account is authenticated but does not yet have a RUC staff profile. An administrator must authorize this account and assign a role before protected student and examination records can be viewed.</p><button onClick={() => { void signOut(); setRoute('login') }} className="mt-4 rounded-lg border border-amber-300 bg-white px-3 py-2 text-xs font-semibold text-amber-950">Sign out</button></section> : <>
 {activePage === 'Overview' && <><div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">{[{label:'Registered students',value:registrations.length,icon:Users,color:'navy'},{label:'Baptismal classes',value:classes.length,icon:BookOpen,color:'green'},{label:'Students passed',value:stats.passed,icon:Check,color:'green'},{label:'Students failed',value:stats.failed,icon:Activity,color:'red'}].map(({label,value,icon:Icon,color})=><div key={label} className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-start justify-between"><span className="text-xs font-medium text-slate-500">{label}</span><span className={`flex size-9 items-center justify-center rounded-xl ${color==='green'?'bg-emerald-50 text-emerald-700':color==='red'?'bg-rose-50 text-rose-700':'bg-slate-100 text-[#102a43]'}`}><Icon size={17}/></span></div><strong className="mt-4 block text-3xl font-semibold tracking-tight text-[#102a43]">{value}</strong><span className="mt-1 block text-[11px] text-slate-400">Across all classes</span></div>)}</div><div className="mt-4 grid gap-4 xl:grid-cols-[1.4fr_.8fr]"><section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold text-slate-800">Recent registrations</h2><p className="mt-1 text-xs text-slate-400">Latest student submissions</p></div><button onClick={()=>setActivePage('Student registrations')} className="text-xs font-semibold text-emerald-800">View all</button></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[500px] text-left text-xs"><thead className="text-[10px] uppercase tracking-wider text-slate-400"><tr><th className="pb-3 font-semibold">Student</th><th className="pb-3 font-semibold">Class</th><th className="pb-3 font-semibold">Level</th><th className="pb-3 font-semibold">Date</th></tr></thead><tbody>{registrations.slice(0,6).map((r)=><tr key={r.id} className="border-t border-slate-100"><td className="py-3"><span className="font-semibold text-slate-800">{r.full_name}</span><span className="mt-1 block text-[10px] text-slate-400">{r.matric_number}</span></td><td className="py-3 text-slate-600">{classes.find(c=>c.id===r.baptismal_class_id)?.class_name ?? '—'}</td><td className="py-3 text-slate-600">{r.level} level</td><td className="py-3 text-slate-500">{formatDate(r.registration_date)}</td></tr>)}</tbody></table>{!registrations.length&&<EmptyPanel text="New registrations will appear here."/>}</div></section><section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><h2 className="text-sm font-semibold text-slate-800">Class activity</h2><p className="mt-1 text-xs text-slate-400">Student distribution across classes</p><div className="mt-5 flex flex-col gap-4">{classCounts.slice(0,6).map((c)=>{const max=Math.max(...classCounts.map(x=>x.enrolled),1);return <div key={c.id}><div className="mb-1.5 flex justify-between text-xs"><span className="font-medium text-slate-700">{c.class_name}</span><span className="text-slate-400">{c.enrolled}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-emerald-600" style={{width:`${(c.enrolled/max)*100}%`}}/></div></div>})}</div></section></div><div className="mt-4 grid gap-4 sm:grid-cols-3"><MiniStat title="Students failed" value={stats.failed} caption="Below pass mark"/><MiniStat title="Pending results" value={stats.pending} caption="Awaiting examination results"/><MiniStat title="Registered for baptism" value={registrations.length} caption="Completed registrations"/></div></>}
 {activePage === 'Student registrations' && <section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="mb-5 flex flex-wrap gap-3"><div className="relative min-w-[220px] flex-1"><Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400"/><input className={`${fieldClass} pl-10`} aria-label="Search students" placeholder="Search name, matric number or department" value={search} onChange={(e)=>setSearch(e.target.value)}/></div><select aria-label="Filter by class" className={`${fieldClass} w-auto min-w-[170px]`} value={filterClass} onChange={(e)=>setFilterClass(e.target.value)}><option value="all">All classes</option>{classes.map(c=><option key={c.id} value={c.id}>{c.class_name}</option>)}</select></div><div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left text-xs"><thead className="bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400"><tr>{['Student','Gender','Level','Department','Baptismal class','Class teacher','Registered'].map(x=><th className="px-3 py-3 font-semibold" key={x}>{x}</th>)}</tr></thead><tbody>{filteredRegs.map((r)=><tr key={r.id} className="border-t border-slate-100 hover:bg-slate-50/70"><td className="px-3 py-3"><button onClick={()=>setDetail(r)} className="text-left font-semibold text-[#102a43] hover:text-emerald-800">{r.full_name}</button><span className="mt-1 block text-[10px] text-slate-400">{r.matric_number}</span></td><td className="px-3 py-3 text-slate-600">{r.gender}</td><td className="px-3 py-3 text-slate-600">{r.level}</td><td className="px-3 py-3 text-slate-600">{r.department}</td><td className="px-3 py-3 text-slate-600">{classes.find(c=>c.id===r.baptismal_class_id)?.class_name ?? '—'}</td><td className="px-3 py-3 text-slate-600">{classes.find(c=>c.id===r.baptismal_class_id)?.class_teacher ?? '—'}</td><td className="px-3 py-3 text-slate-500">{formatDate(r.registration_date)}</td></tr>)}</tbody></table>{!filteredRegs.length&&<EmptyPanel text="No registrations match your search."/>}</div></section>}
 {activePage === 'Manage classes' && <><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{classCounts.map((c)=><article key={c.id} className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-start justify-between"><div><span className="text-[10px] font-bold uppercase tracking-[.15em] text-emerald-700">BAPTISMAL CLASS</span><h2 className="mt-2 text-lg font-semibold text-[#102a43]">{c.class_name}</h2></div><span className="flex size-9 items-center justify-center rounded-xl bg-emerald-50 text-emerald-800"><BookOpen size={17}/></span></div><div className="mt-5 border-t border-slate-100 pt-4 text-xs"><div className="flex justify-between py-1.5"><span className="text-slate-400">Class teacher</span><span className="font-medium text-slate-700">{c.class_teacher}</span></div><div className="flex justify-between py-1.5"><span className="text-slate-400">Assistant</span><span className="font-medium text-slate-700">{c.assistant_teacher}</span></div></div><div className="mt-4 grid grid-cols-3 gap-2"><SmallCount label="Students" value={c.enrolled}/><SmallCount label="Passed" value={c.passed}/><SmallCount label="Failed" value={c.failed}/></div>{staffRole==='admin'&&<button onClick={()=>void removeClass(c.id)} className="mt-4 text-xs font-semibold text-rose-700">Remove class</button>}</article>)}</section>{staffRole==='admin'&&<form onSubmit={addClass} className="mt-5 rounded-2xl border border-slate-200 bg-white p-5"><h2 className="font-semibold text-[#102a43]">Add a baptismal class</h2><div className="mt-4 grid gap-3 sm:grid-cols-3"><input className={fieldClass} required placeholder="Class name" value={newClass.class_name} onChange={e=>setNewClass({...newClass,class_name:e.target.value})}/><input className={fieldClass} required placeholder="Class teacher" value={newClass.class_teacher} onChange={e=>setNewClass({...newClass,class_teacher:e.target.value})}/><input className={fieldClass} placeholder="Assistant teacher" value={newClass.assistant_teacher} onChange={e=>setNewClass({...newClass,assistant_teacher:e.target.value||'Not assigned'})}/></div><button className="mt-3 flex items-center gap-2 rounded-lg bg-[#102a43] px-4 py-2.5 text-xs font-semibold text-white"><Plus size={14}/> Add class</button></form>}</>}
 {activePage === 'Upload results' && <><section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><h2 className="text-sm font-semibold text-slate-800">Choose your class</h2><p className="mt-1 text-xs text-slate-500">You can only enter results for a class assigned to your staff profile.</p><select className={`${fieldClass} mt-4 max-w-lg`} value={classChoice} onChange={e=>setClassChoice(e.target.value)}><option value="">Select a baptismal class</option>{classes.map(c=><option key={c.id} value={c.id}>{c.class_name} — {c.class_teacher}</option>)}</select>{classes.find(c=>c.id===classChoice)&&<div className="mt-3 flex flex-wrap gap-2 text-xs text-slate-600"><span className="rounded-lg bg-slate-50 px-3 py-2">Teacher: {classes.find(c=>c.id===classChoice)?.class_teacher}</span><span className="rounded-lg bg-slate-50 px-3 py-2">Assistant: {classes.find(c=>c.id===classChoice)?.assistant_teacher}</span></div>}</section><section className="mt-4 rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-sm font-semibold text-slate-800">Examination entries</h2><p className="mt-1 text-xs text-slate-500">Pass mark: {passMark}/70 · Existing registrations are matched by matric number.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>exportCsv(['Student Name','Matric Number','Examination Score (out of 70)','Remarks'],[['','', '', '']], 'ruc-results-template.csv')} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold text-slate-600">Download CSV template</button><label className="cursor-pointer rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-900">Import CSV<input className="sr-only" type="file" accept=".csv,text/csv" onChange={e=>void uploadCsv(e.target.files?.[0])}/></label></div></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[760px] text-left text-xs"><thead className="bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400"><tr>{['Student name','Matric number','Score / 70','Result status','Remarks',''].map(h=><th key={h} className="px-2 py-3 font-semibold">{h}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i} className="border-t border-slate-100"><td className="px-2 py-2"><input className="w-full rounded-lg border border-slate-200 px-2.5 py-2" placeholder="Full name" value={row.student_name} onChange={e=>setRows(rows.map((r,j)=>j===i?{...r,student_name:e.target.value}:r))}/></td><td className="px-2 py-2"><input className="w-full rounded-lg border border-slate-200 px-2.5 py-2" placeholder="Matric no." value={row.matric_number} onChange={e=>setRows(rows.map((r,j)=>j===i?{...r,matric_number:e.target.value}:r))}/>{row.matric_number&&registrations.some(r=>r.matric_number===row.matric_number.toUpperCase()&&r.baptismal_class_id!==classChoice)&&<span className="mt-1 block text-[9px] text-amber-700">Unregistered in this class</span>}</td><td className="px-2 py-2"><input className="w-24 rounded-lg border border-slate-200 px-2.5 py-2" type="number" min="0" max="70" step="0.01" placeholder="0" value={row.examination_score} onChange={e=>setRows(rows.map((r,j)=>j===i?{...r,examination_score:e.target.value}:r))}/></td><td className="px-2 py-2"><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${row.examination_score===''?'bg-amber-50 text-amber-800':Number(row.examination_score)>=passMark?'bg-emerald-50 text-emerald-800':'bg-rose-50 text-rose-800'}`}>{row.examination_score===''?'PENDING':Number(row.examination_score)>=passMark?'PASS':'FAIL'}</span></td><td className="px-2 py-2"><input className="w-full rounded-lg border border-slate-200 px-2.5 py-2" placeholder="Optional" value={row.remarks} onChange={e=>setRows(rows.map((r,j)=>j===i?{...r,remarks:e.target.value}:r))}/></td><td className="px-2 py-2"><button aria-label="Remove row" onClick={()=>setRows(rows.filter((_,j)=>j!==i))} className="text-slate-400 hover:text-rose-700"><X size={15}/></button></td></tr>)}</tbody></table></div><div className="mt-4 flex flex-wrap justify-between gap-3"><button onClick={()=>setRows([...rows,{student_name:'',matric_number:'',baptismal_class_id:classChoice,examination_score:'',remarks:''}])} className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2.5 text-xs font-semibold text-slate-700"><Plus size={14}/> Add student</button><button disabled={saving} onClick={()=>void saveResults()} className="flex items-center gap-2 rounded-lg bg-[#102a43] px-4 py-2.5 text-xs font-semibold text-white disabled:opacity-60">{saving?<LoaderCircle size={14} className="animate-spin"/>:<Check size={14}/>} Save results</button></div></section></>}
 {activePage === 'Examination results' && <section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-sm font-semibold text-slate-800">Saved examination records</h2><p className="mt-1 text-xs text-slate-500">Results are calculated against the configured {passMark}/70 pass mark.</p></div><select className={`${fieldClass} w-auto`} value={filterClass} onChange={e=>setFilterClass(e.target.value)}><option value="all">All classes</option>{classes.map(c=><option key={c.id} value={c.id}>{c.class_name}</option>)}</select></div><div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left text-xs"><thead className="bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400"><tr>{['Student','Class','Score','Status','Remarks'].map(x=><th key={x} className="px-3 py-3 font-semibold">{x}</th>)}</tr></thead><tbody>{results.filter(r=>filterClass==='all'||r.baptismal_class_id===filterClass).map(r=><tr key={r.id} className="border-t border-slate-100"><td className="px-3 py-3 font-semibold text-slate-800">{r.student_name}<span className="mt-1 block text-[10px] font-normal text-slate-400">{r.matric_number} · {registrations.some(s=>s.matric_number===r.matric_number)?'Registered':'Unregistered'}</span></td><td className="px-3 py-3 text-slate-600">{classes.find(c=>c.id===r.baptismal_class_id)?.class_name}</td><td className="px-3 py-3 text-slate-600">{r.examination_score}/70</td><td className="px-3 py-3"><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${Number(r.examination_score)>=passMark?'bg-emerald-50 text-emerald-800':'bg-rose-50 text-rose-800'}`}>{Number(r.examination_score)>=passMark?'PASS':'FAIL'}</span></td><td className="px-3 py-3 text-slate-500">{r.remarks||'—'}</td></tr>)}</tbody></table>{!results.length&&<EmptyPanel text="Examination results will appear here once submitted."/>}</div></section>}
 {activePage === 'Teachers & assistants' && <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{classes.map(c=><div key={c.id} className="rounded-2xl border border-slate-200 bg-white p-5"><span className="text-xs font-bold text-emerald-800">{c.class_name}</span><div className="mt-4 flex items-center gap-3"><Avatar name={c.class_teacher}/><div><span className="block text-[10px] uppercase tracking-wider text-slate-400">Class teacher</span><strong className="mt-1 block text-sm text-slate-800">{c.class_teacher}</strong></div></div><div className="mt-4 flex items-center gap-3"><Avatar name={c.assistant_teacher}/><div><span className="block text-[10px] uppercase tracking-wider text-slate-400">Assistant teacher</span><strong className="mt-1 block text-sm text-slate-800">{c.assistant_teacher}</strong></div></div></div>)}</section>}
 {activePage === 'Reports & analytics' && <><div className="grid gap-4 sm:grid-cols-3"><MiniStat title="Total registered" value={registrations.length} caption="Students across all classes"/><MiniStat title="Pass percentage" value={`${results.length?Math.round((stats.passed/results.length)*100):0}%`} caption="Based on recorded results"/><MiniStat title="Awaiting results" value={stats.pending} caption="Registered students without results"/></div><section className="mt-4 rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-sm font-semibold text-slate-800">Class performance</h2><p className="mt-1 text-xs text-slate-500">Student registrations and examination outcomes by class</p></div><button onClick={()=>exportCsv(['Class','Students','Passed','Failed','Pass percentage'],classCounts.map(c=>[c.class_name,String(c.enrolled),String(c.passed),String(c.failed),`${c.passed+c.failed?Math.round(c.passed/(c.passed+c.failed)*100):0}%`]),'ruc-class-report.csv')} className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold"><ArrowDownToLine size={14}/> Export report</button></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[580px] text-left text-xs"><thead className="bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400"><tr>{['Class','Students','Passed','Failed','Pass rate'].map(x=><th key={x} className="px-3 py-3 font-semibold">{x}</th>)}</tr></thead><tbody>{classCounts.map(c=><tr key={c.id} className="border-t border-slate-100"><td className="px-3 py-3 font-semibold text-slate-800">{c.class_name}</td><td className="px-3 py-3">{c.enrolled}</td><td className="px-3 py-3 text-emerald-800">{c.passed}</td><td className="px-3 py-3 text-rose-700">{c.failed}</td><td className="px-3 py-3"><div className="flex items-center gap-2"><span className="h-1.5 w-20 overflow-hidden rounded-full bg-slate-100"><span className="block h-full rounded-full bg-emerald-600" style={{width:`${c.passed+c.failed?c.passed/(c.passed+c.failed)*100:0}%`}}/></span>{c.passed+c.failed?Math.round(c.passed/(c.passed+c.failed)*100):0}%</div></td></tr>)}</tbody></table></div></section></>}
 {activePage === 'Settings' && <section className="max-w-2xl rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex items-start gap-3"><span className="flex size-10 items-center justify-center rounded-xl bg-emerald-50 text-emerald-800"><Settings size={18}/></span><div><h2 className="text-sm font-semibold text-slate-800">Examination settings</h2><p className="mt-1 text-xs leading-5 text-slate-500">Set the minimum score out of 70 required to pass. This is applied to new and saved result status displays.</p></div></div><form onSubmit={async e=>{e.preventDefault();const {error}=await supabase.from('system_settings').update({examination_pass_mark:passMark,updated_at:new Date().toISOString()}).eq('id',true);setNotice(error?'Could not save settings. Admin access is required.':'Pass mark updated successfully.')}} className="mt-6 flex flex-wrap items-end gap-3"><label className="flex-1"><span className={classesLabel}>Passing score (out of 70)</span><input className={fieldClass} type="number" min="0" max="70" step="1" value={passMark} onChange={e=>setPassMark(Number(e.target.value))}/></label><button className="rounded-xl bg-[#102a43] px-5 py-3 text-sm font-semibold text-white">Save settings</button></form><p className="mt-4 text-xs text-slate-400">Only an administrator can change the pass mark.</p><div className="my-6 border-t border-slate-100"/><div><h3 className="text-sm font-semibold text-slate-800">Change administrator password</h3><p className="mt-1 text-xs text-slate-500">Choose a new password with at least 8 characters.</p>{passwordNotice&&<p role="status" className="mt-3 text-xs font-medium text-emerald-800">{passwordNotice}</p>}<form className="mt-4 flex flex-wrap items-end gap-3" onSubmit={async e=>{e.preventDefault();const values=new FormData(e.currentTarget);const password=String(values.get('new-password')??'');const confirmation=String(values.get('confirm-password')??'');if(password.length<8){setPasswordNotice('Use at least 8 characters.');return}if(password!==confirmation){setPasswordNotice('The passwords do not match.');return}const {error}=await supabase.auth.updateUser({password});setPasswordNotice(error?'Unable to update the password. Sign in again and retry.':'Administrator password updated. Use the new password the next time you sign in.');if(!error)e.currentTarget.reset()}}><label className="flex-1"><span className={classesLabel}>New password</span><input className={fieldClass} name="new-password" type="password" minLength={8} required autoComplete="new-password"/></label><label className="flex-1"><span className={classesLabel}>Confirm password</span><input className={fieldClass} name="confirm-password" type="password" minLength={8} required autoComplete="new-password"/></label><button className="rounded-xl border border-slate-200 bg-white px-5 py-3 text-sm font-semibold text-slate-700">Update password</button></form></div></section>}
 </>}</main></div>{detail&&<div role="dialog" aria-modal="true" aria-labelledby="student-detail-title" className="fixed inset-0 z-30 flex items-center justify-center bg-slate-950/40 p-4" onClick={()=>setDetail(null)}><section onClick={e=>e.stopPropagation()} className="max-h-[90vh] w-full max-w-xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between"><div><span className="text-xs font-semibold uppercase tracking-widest text-emerald-700">Student profile</span><h2 id="student-detail-title" className="mt-2 text-xl font-semibold text-[#102a43]">{detail.full_name}</h2><p className="mt-1 text-sm text-slate-500">{detail.matric_number}</p></div><button aria-label="Close profile" onClick={()=>setDetail(null)}><X size={18}/></button></div><dl className="mt-6 grid grid-cols-2 gap-x-5 gap-y-4 text-sm">{[['Gender',detail.gender],['Level',`${detail.level} level`],['Department',detail.department],['Baptismal class',classes.find(c=>c.id===detail.baptismal_class_id)?.class_name??''],['Class teacher',classes.find(c=>c.id===detail.baptismal_class_id)?.class_teacher??''],['Registration date',formatDate(detail.registration_date)],['Reason for baptism',detail.reason_for_baptism],['Class feedback',detail.class_feedback||'No feedback provided']].map(([k,v])=><div key={k} className="col-span-2 border-b border-slate-100 pb-3"><dt className="text-[10px] font-semibold uppercase tracking-wider text-slate-400">{k}</dt><dd className="mt-1 text-sm leading-6 text-slate-700">{v}</dd></div>)}</dl><button onClick={()=>setDetail(null)} className="mt-5 rounded-lg border border-slate-200 px-4 py-2 text-xs font-semibold text-slate-700">Close</button></section></div>}</div>
}
function MiniStat({title,value,caption}:{title:string;value:number|string;caption:string}){return <div className="rounded-2xl border border-slate-200 bg-white p-5"><p className="text-xs font-medium text-slate-500">{title}</p><strong className="mt-3 block text-2xl font-semibold text-[#102a43]">{value}</strong><p className="mt-1 text-[11px] text-slate-400">{caption}</p></div>}
function SmallCount({label,value}:{label:string;value:number}){return <div className="rounded-xl bg-slate-50 p-2.5"><span className="block text-[10px] text-slate-400">{label}</span><strong className="mt-1 block text-sm text-slate-800">{value}</strong></div>}
function Avatar({name}:{name:string}){return <span className="flex size-9 items-center justify-center rounded-full bg-[#edf3f1] text-xs font-bold text-emerald-900">{name.split(' ').map(n=>n[0]).join('').slice(0,2)}</span>}
function EmptyPanel({text}:{text:string}){return <div className="flex flex-col items-center justify-center py-12 text-center"><span className="flex size-10 items-center justify-center rounded-full bg-slate-50 text-slate-400"><Users size={18}/></span><p className="mt-3 text-sm font-medium text-slate-600">Nothing to show yet</p><p className="mt-1 text-xs text-slate-400">{text}</p></div>}
